-- Tags: long
-- long: many statements; over the time limit of the flaky check under the thread fuzzer.

-- SHARED added and removed by ALTER MODIFY COLUMN, lazily (a type hint change is metadata only) and by mutation, parts
-- of both layouts read together and merged, path type changes, a column absent from the part, and the layout of each
-- part through system.parts_columns. Compared with a Memory table of the target type without SHARED; each line prints
-- an equality flag.

DROP TABLE IF EXISTS mem; CREATE TABLE mem (x UInt64, json JSON(a UInt64, b String, c Array(UInt8))) ENGINE = Memory; INSERT INTO mem SELECT number, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(40);
DROP TABLE IF EXISTS nmem; CREATE TABLE nmem (x UInt64, json JSON(a.x UInt64, a.y String, b UInt64)) ENGINE = Memory; INSERT INTO nmem SELECT number, concat('{"a":{"x":', toString(number), ',"y":"', repeat('y', number % 5), '"},"b":', toString(number * 2), ',"e":', toString(number), '}') FROM numbers(40);
SELECT '-- w: shape A, the plain type to SHARED and back, lazily';
DROP TABLE IF EXISTS a_w; CREATE TABLE a_w (x UInt64, json JSON(a UInt64, b String, c Array(UInt8))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1;
INSERT INTO a_w SELECT number, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(20);
ALTER TABLE a_w MODIFY COLUMN json JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8)) SETTINGS enable_json_lazy_type_hints = 1;
SELECT 'a_w mutations', count() FROM system.mutations WHERE database = currentDatabase() AND table = 'a_w';
INSERT INTO a_w SELECT number, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(20, 20);
SELECT 'a_w layout', name, arrayExists(s -> s LIKE '%object_typed_shared_data%', substreams), arrayExists(s -> s LIKE '%json.a%' OR s LIKE '%json.b%', substreams) FROM system.parts_columns WHERE database = currentDatabase() AND table = 'a_w' AND column = 'json' AND active ORDER BY name;
SELECT 'a_w [json]', (SELECT arraySort(groupArray((x, toString(json)))) FROM a_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem );
SELECT 'a_w [json.a]', (SELECT arraySort(groupArray((x, toString(json.a)))) FROM a_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json.a)))) FROM mem );
SELECT 'a_w [json.c.size0]', (SELECT arraySort(groupArray((x, toString(json.c.size0)))) FROM a_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json.c.size0)))) FROM mem );
SELECT 'a_w [json.d]', (SELECT arraySort(groupArray((x, toString(json.d)))) FROM a_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json.d)))) FROM mem );
SELECT 'a_w [(json, json.a)]', (SELECT arraySort(groupArray((x, toString((json, json.a))))) FROM a_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((json, json.a))))) FROM mem );
SELECT 'a_w [(json.c.size0, json)]', (SELECT arraySort(groupArray((x, toString((json.c.size0, json))))) FROM a_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((json.c.size0, json))))) FROM mem );
SELECT 'a_w [json] max_block_size = 5', (SELECT arraySort(groupArray((x, toString(json)))) FROM a_w  SETTINGS max_threads = 1, max_block_size = 5) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem );
SELECT 'a_w [(json.a, json)] max_block_size = 5', (SELECT arraySort(groupArray((x, toString((json.a, json))))) FROM a_w  SETTINGS max_threads = 1, max_block_size = 5) = (SELECT arraySort(groupArray((x, toString((json.a, json))))) FROM mem );
SELECT 'a_w [json] max_threads = 4, max_block_size = 5', (SELECT arraySort(groupArray((x, toString(json)))) FROM a_w  SETTINGS max_threads = 1, max_threads = 4, max_block_size = 5) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem );
SELECT 'a_w [(json.a, json)] max_threads = 4, max_block_size = 5', (SELECT arraySort(groupArray((x, toString((json.a, json))))) FROM a_w  SETTINGS max_threads = 1, max_threads = 4, max_block_size = 5) = (SELECT arraySort(groupArray((x, toString((json.a, json))))) FROM mem );
SELECT 'a_w paths over the old part', JSONDynamicPaths(json), JSONSharedDataPaths(json), JSONAllPaths(json) FROM a_w WHERE x = 2;
OPTIMIZE TABLE a_w FINAL;
SELECT 'a_w layout', name, arrayExists(s -> s LIKE '%object_typed_shared_data%', substreams), arrayExists(s -> s LIKE '%json.a%' OR s LIKE '%json.b%', substreams) FROM system.parts_columns WHERE database = currentDatabase() AND table = 'a_w' AND column = 'json' AND active ORDER BY name;
SELECT 'a_w [json]', (SELECT arraySort(groupArray((x, toString(json)))) FROM a_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem );
SELECT 'a_w [(json.c.size0, json.b)] max_block_size = 7', (SELECT arraySort(groupArray((x, toString((json.c.size0, json.b))))) FROM a_w  SETTINGS max_threads = 1, max_block_size = 7) = (SELECT arraySort(groupArray((x, toString((json.c.size0, json.b))))) FROM mem );
CHECK TABLE a_w SETTINGS check_query_single_value_result = 1;
ALTER TABLE a_w MODIFY COLUMN json JSON(a UInt64, b String, c Array(UInt8)) SETTINGS enable_json_lazy_type_hints = 1;
SELECT 'a_w mutations', count() FROM system.mutations WHERE database = currentDatabase() AND table = 'a_w';
INSERT INTO a_w SELECT number + 100, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(4);
SELECT 'a_w layout', name, arrayExists(s -> s LIKE '%object_typed_shared_data%', substreams), arrayExists(s -> s LIKE '%json.a%' OR s LIKE '%json.b%', substreams) FROM system.parts_columns WHERE database = currentDatabase() AND table = 'a_w' AND column = 'json' AND active ORDER BY name;
SELECT 'a_w [json] WHERE x < 40', (SELECT arraySort(groupArray((x, toString(json)))) FROM a_w WHERE x < 40 SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem WHERE x < 40);
SELECT 'a_w [(json.a, json.c.size0)] max_block_size = 5 WHERE x < 40', (SELECT arraySort(groupArray((x, toString((json.a, json.c.size0))))) FROM a_w WHERE x < 40 SETTINGS max_threads = 1, max_block_size = 5) = (SELECT arraySort(groupArray((x, toString((json.a, json.c.size0))))) FROM mem WHERE x < 40);
SELECT 'a_w back', count(), sum(json.a) FROM a_w;
OPTIMIZE TABLE a_w FINAL;
SELECT 'a_w layout', name, arrayExists(s -> s LIKE '%object_typed_shared_data%', substreams), arrayExists(s -> s LIKE '%json.a%' OR s LIKE '%json.b%', substreams) FROM system.parts_columns WHERE database = currentDatabase() AND table = 'a_w' AND column = 'json' AND active ORDER BY name;
SELECT 'a_w [json] WHERE x < 40', (SELECT arraySort(groupArray((x, toString(json)))) FROM a_w WHERE x < 40 SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem WHERE x < 40);
CHECK TABLE a_w SETTINGS check_query_single_value_result = 1;
DROP TABLE a_w;
SELECT '-- w: shape A on a nested type, with the sub-object';
DROP TABLE IF EXISTS n_w; CREATE TABLE n_w (x UInt64, json JSON(a.x UInt64, a.y String, b UInt64)) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1;
INSERT INTO n_w SELECT number, concat('{"a":{"x":', toString(number), ',"y":"', repeat('y', number % 5), '"},"b":', toString(number * 2), ',"e":', toString(number), '}') FROM numbers(20);
ALTER TABLE n_w MODIFY COLUMN json JSON(SHARED a.x UInt64, SHARED a.y String, SHARED b UInt64) SETTINGS enable_json_lazy_type_hints = 1;
INSERT INTO n_w SELECT number, concat('{"a":{"x":', toString(number), ',"y":"', repeat('y', number % 5), '"},"b":', toString(number * 2), ',"e":', toString(number), '}') FROM numbers(20, 20);
SELECT 'n_w [json]', (SELECT arraySort(groupArray((x, toString(json)))) FROM n_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM nmem );
SELECT 'n_w [json] max_block_size = 7', (SELECT arraySort(groupArray((x, toString(json)))) FROM n_w  SETTINGS max_threads = 1, max_block_size = 7) = (SELECT arraySort(groupArray((x, toString(json)))) FROM nmem );
SELECT 'n_w [json.^a]', (SELECT arraySort(groupArray((x, toString(json.^a)))) FROM n_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json.^a)))) FROM nmem );
SELECT 'n_w [json.^a] max_block_size = 7', (SELECT arraySort(groupArray((x, toString(json.^a)))) FROM n_w  SETTINGS max_threads = 1, max_block_size = 7) = (SELECT arraySort(groupArray((x, toString(json.^a)))) FROM nmem );
SELECT 'n_w [json.a.x]', (SELECT arraySort(groupArray((x, toString(json.a.x)))) FROM n_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json.a.x)))) FROM nmem );
SELECT 'n_w [json.a.x] max_block_size = 7', (SELECT arraySort(groupArray((x, toString(json.a.x)))) FROM n_w  SETTINGS max_threads = 1, max_block_size = 7) = (SELECT arraySort(groupArray((x, toString(json.a.x)))) FROM nmem );
SELECT 'n_w [json.b]', (SELECT arraySort(groupArray((x, toString(json.b)))) FROM n_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json.b)))) FROM nmem );
SELECT 'n_w [json.b] max_block_size = 7', (SELECT arraySort(groupArray((x, toString(json.b)))) FROM n_w  SETTINGS max_threads = 1, max_block_size = 7) = (SELECT arraySort(groupArray((x, toString(json.b)))) FROM nmem );
SELECT 'n_w [(json.^a, json.b)]', (SELECT arraySort(groupArray((x, toString((json.^a, json.b))))) FROM n_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((json.^a, json.b))))) FROM nmem );
SELECT 'n_w [(json.^a, json.b)] max_block_size = 7', (SELECT arraySort(groupArray((x, toString((json.^a, json.b))))) FROM n_w  SETTINGS max_threads = 1, max_block_size = 7) = (SELECT arraySort(groupArray((x, toString((json.^a, json.b))))) FROM nmem );
SELECT 'n_w [(json.a.y, json.^a, json.e)]', (SELECT arraySort(groupArray((x, toString((json.a.y, json.^a, json.e))))) FROM n_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((json.a.y, json.^a, json.e))))) FROM nmem );
SELECT 'n_w [(json.a.y, json.^a, json.e)] max_block_size = 7', (SELECT arraySort(groupArray((x, toString((json.a.y, json.^a, json.e))))) FROM n_w  SETTINGS max_threads = 1, max_block_size = 7) = (SELECT arraySort(groupArray((x, toString((json.a.y, json.^a, json.e))))) FROM nmem );
OPTIMIZE TABLE n_w FINAL;
SELECT 'n_w [json.^a]', (SELECT arraySort(groupArray((x, toString(json.^a)))) FROM n_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json.^a)))) FROM nmem );
SELECT 'n_w [(json, json.^a)] max_block_size = 5', (SELECT arraySort(groupArray((x, toString((json, json.^a))))) FROM n_w  SETTINGS max_threads = 1, max_block_size = 5) = (SELECT arraySort(groupArray((x, toString((json, json.^a))))) FROM nmem );
CHECK TABLE n_w SETTINGS check_query_single_value_result = 1;
DROP TABLE n_w;
