DROP TABLE IF EXISTS b_w; CREATE TABLE b_w (x UInt64, json JSON(max_dynamic_paths = 2)) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1;
