SELECT 'b_w paths before', JSONDynamicPaths(json), JSONSharedDataPaths(json) FROM b_w WHERE x = 2;
ALTER TABLE b_w MODIFY COLUMN json JSON(max_dynamic_paths = 2, SHARED a UInt64, SHARED c Array(UInt8)) SETTINGS enable_json_lazy_type_hints = 1;
