SELECT 'b_w [json.d] max_block_size = 7', (SELECT arraySort(groupArray((x, toString(json.d)))) FROM b_w  SETTINGS max_threads = 1, max_block_size = 7) = (SELECT arraySort(groupArray((x, toString(json.d)))) FROM bmem );
SELECT 'b_w [json.b]', (SELECT arraySort(groupArray((x, toString(json.b)))) FROM b_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json.b)))) FROM bmem );
SELECT 'b_w [json.b] max_block_size = 7', (SELECT arraySort(groupArray((x, toString(json.b)))) FROM b_w  SETTINGS max_threads = 1, max_block_size = 7) = (SELECT arraySort(groupArray((x, toString(json.b)))) FROM bmem );
