SELECT '-- w: shape C, the same ALTER as a mutation, every part rewritten';
DROP TABLE IF EXISTS c_w; CREATE TABLE c_w (x UInt64, json JSON(a UInt64, b String, c Array(UInt8))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1;
INSERT INTO c_w SELECT number, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(20); INSERT INTO c_w SELECT number, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(20, 20);
