INSERT INTO cont SELECT number, map('k', CAST(concat('{"a":', toString(number), '}'), 'JSON(a UInt64)')), tuple(CAST(concat('{"a":', toString(number * 2), '}'), 'JSON(a UInt64)')) FROM numbers(20);
ALTER TABLE cont MODIFY COLUMN m Map(String, JSON(SHARED a UInt64)), MODIFY COLUMN t Tuple(j JSON(SHARED a UInt64)) SETTINGS enable_json_lazy_type_hints = 1, mutations_sync = 2;
