SELECT '-- path type changes and SHARED paths added or removed one at a time';
DROP TABLE IF EXISTS p_w; CREATE TABLE p_w (x UInt64, json JSON(SHARED a UInt64, SHARED c String)) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1;
INSERT INTO p_w SELECT number, concat('{"a":', toString(number), ',"b":', toString(number * 2), ',"c":"c', toString(number), '","q":{"r":"r', toString(number), '"}}') FROM numbers(20);
ALTER TABLE p_w MODIFY COLUMN json JSON(SHARED a UInt64, SHARED b UInt64, SHARED c String) SETTINGS enable_json_lazy_type_hints = 1;
SELECT 'p_w mutations', count() FROM system.mutations WHERE database = currentDatabase() AND table = 'p_w';
SELECT 'p_w added', count(), sum(json.a), sum(json.b), argMin(json.c, x), toTypeName(json.b) FROM p_w SETTINGS max_threads = 1;
INSERT INTO p_w SELECT number, concat('{"a":', toString(number), ',"b":', toString(number * 2), ',"c":"c', toString(number), '","q":{"r":"r', toString(number), '"}}') FROM numbers(20, 20);
SELECT 'p_w two layouts', count(), sum(json.a), sum(json.b), argMin(json.c, x) FROM p_w SETTINGS max_threads = 1, max_block_size = 7;
ALTER TABLE p_w MODIFY COLUMN json JSON(SHARED a UInt64, SHARED b UInt64, SHARED c String, SHARED q.r String) SETTINGS enable_json_lazy_type_hints = 1;
SELECT 'p_w nested path added', count(), uniqExact(json.q.r), (SELECT json.^q FROM p_w WHERE x = 3), (SELECT json.^q FROM p_w WHERE x = 23) FROM p_w SETTINGS max_threads = 1;
OPTIMIZE TABLE p_w FINAL;
SELECT 'p_w merged', count(), sum(json.a), sum(json.b), uniqExact(json.q.r), uniqExact(_part) FROM p_w SETTINGS max_threads = 1;
ALTER TABLE p_w MODIFY COLUMN json JSON(SHARED a UInt64, SHARED c String) SETTINGS enable_json_lazy_type_hints = 1;
SELECT '-- the removed path is a dynamic path again; its typed subcolumn over the old Wide part reads as NULL, a pre-existing limitation of lazy type hints that the plain type shares (Compact parts give the values)';
SELECT 'p_w removed', count(), sum(json.a), argMin(json.c, x), toTypeName(json.b), sum(json.b.:Int64), (SELECT sum(json.b.:Int64) FROM (SELECT json FROM p_w)) FROM p_w SETTINGS max_threads = 1;
ALTER TABLE p_w MODIFY COLUMN json JSON(SHARED a String, SHARED c String) SETTINGS mutations_sync = 2;
SELECT 'p_w mutations', count() FROM system.mutations WHERE database = currentDatabase() AND table = 'p_w';
SELECT 'p_w a to String', toTypeName(json.a), sum(toUInt64(json.a)), argMin(json.a, x) FROM p_w SETTINGS max_threads = 1;
ALTER TABLE p_w MODIFY COLUMN json JSON() SETTINGS enable_json_lazy_type_hints = 1;
INSERT INTO p_w SELECT number + 100, concat('{"a":"', toString(number), '","c":"c"}') FROM numbers(4);
SELECT 'p_w hints dropped', count(), toTypeName(json.a), uniqExact(json.a), sum(json.c = 'c') FROM p_w SETTINGS max_threads = 1;
SELECT 'p_w layout', name, arrayExists(s -> s LIKE '%object_typed_shared_data%', substreams), arrayExists(s -> s LIKE '%json.a%' OR s LIKE '%json.b%', substreams) FROM system.parts_columns WHERE database = currentDatabase() AND table = 'p_w' AND column = 'json' AND active ORDER BY name;
ALTER TABLE p_w MODIFY COLUMN json String SETTINGS mutations_sync = 2;
SELECT 'p_w to String', count(), sum(length(json) > 0), argMin(json, x) FROM p_w SETTINGS max_threads = 1;
CHECK TABLE p_w SETTINGS check_query_single_value_result = 1;
