SELECT 'p_cn removed', count(), sum(json.a), argMin(json.c, x), toTypeName(json.b), sum(json.b.:Int64), (SELECT sum(json.b.:Int64) FROM (SELECT json FROM p_cn)) FROM p_cn SETTINGS max_threads = 1;
