SELECT '-- a column absent from the part: added by ALTER or cleared, its SHARED paths read as defaults';
DROP TABLE IF EXISTS ab_w; CREATE TABLE ab_w (x UInt64, json JSON(SHARED a UInt64)) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1;
INSERT INTO ab_w SELECT number, concat('{"a":', toString(number), '}') FROM numbers(8);
ALTER TABLE ab_w ADD COLUMN json2 JSON(SHARED a UInt64, SHARED c Array(UInt8), SHARED p.x String);
SELECT 'ab_w added column over the old part', json2, json2.a, json2.c.size0, json2.^p, json2['a'], json2.p.x, json2.c FROM ab_w WHERE x = 3 SETTINGS optimize_functions_to_subcolumns = 1;
INSERT INTO ab_w SELECT number, concat('{"a":', toString(number), '}'), concat('{"a":', toString(number), ',"c":', toString(range(number % 3)), ',"p":{"x":"x', toString(number), '"}}') FROM numbers(8, 8);
SELECT 'ab_w old and new parts together', count(), sum(json2.a), sum(json2.c.size0), countIf(json2.p.x = ''), sum(json2['a']) FROM ab_w SETTINGS max_threads = 1, optimize_functions_to_subcolumns = 1;
DROP TABLE IF EXISTS abmem; CREATE TABLE abmem (x UInt64, json JSON(a UInt64), json2 JSON(a UInt64, c Array(UInt8), p.x String)) ENGINE = Memory; INSERT INTO abmem SELECT number, concat('{"a":', toString(number), '}'), if(number < 8, CAST('{}', 'JSON(a UInt64, c Array(UInt8), p.x String)'), concat('{"a":', toString(number), ',"c":', toString(range(number % 3)), ',"p":{"x":"x', toString(number), '"}}')) FROM numbers(16);
SELECT 'ab_w [(json2, json2.a, json2.^p, json2.c.size0)] max_block_size = 5', (SELECT arraySort(groupArray((x, toString((json2, json2.a, json2.^p, json2.c.size0))))) FROM ab_w  SETTINGS max_threads = 1, max_block_size = 5) = (SELECT arraySort(groupArray((x, toString((json2, json2.a, json2.^p, json2.c.size0))))) FROM abmem );
SELECT 'ab_w [(json, json2)] max_block_size = 5', (SELECT arraySort(groupArray((x, toString((json, json2))))) FROM ab_w  SETTINGS max_threads = 1, max_block_size = 5) = (SELECT arraySort(groupArray((x, toString((json, json2))))) FROM abmem );
SELECT 'ab_w [json2.p.x] max_block_size = 5', (SELECT arraySort(groupArray((x, toString(json2.p.x)))) FROM ab_w  SETTINGS max_threads = 1, max_block_size = 5) = (SELECT arraySort(groupArray((x, toString(json2.p.x)))) FROM abmem );
ALTER TABLE ab_w CLEAR COLUMN json2 IN PARTITION tuple() SETTINGS mutations_sync = 2;
SELECT 'ab_w cleared column', count(), sum(json2.a), sum(json2.c.size0), countIf(json2.p.x = ''), uniqExact(toString(json2)) FROM ab_w SETTINGS max_threads = 1;
CHECK TABLE ab_w SETTINGS check_query_single_value_result = 1;
DROP TABLE ab_w; DROP TABLE abmem;
