SELECT 'ab_cn [(json2, json2.a, json2.^p, json2.c.size0)] max_block_size = 5', (SELECT arraySort(groupArray((x, toString((json2, json2.a, json2.^p, json2.c.size0))))) FROM ab_cn  SETTINGS max_threads = 1, max_block_size = 5) = (SELECT arraySort(groupArray((x, toString((json2, json2.a, json2.^p, json2.c.size0))))) FROM abmem );
