SELECT '-- ATTACH PARTITION FROM a table of the same SHARED type';
DROP TABLE IF EXISTS at1; DROP TABLE IF EXISTS at2;
CREATE TABLE at1 (x UInt64, json JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1; CREATE TABLE at2 AS at1;
INSERT INTO at1 SELECT number, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(40);
ALTER TABLE at2 ATTACH PARTITION tuple() FROM at1;
SELECT 'at2 [json]', (SELECT arraySort(groupArray((x, toString(json)))) FROM at2  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem );
SELECT 'at2 [(json.a, json.c.size0)] max_block_size = 7', (SELECT arraySort(groupArray((x, toString((json.a, json.c.size0))))) FROM at2  SETTINGS max_threads = 1, max_block_size = 7) = (SELECT arraySort(groupArray((x, toString((json.a, json.c.size0))))) FROM mem );
CHECK TABLE at2 SETTINGS check_query_single_value_result = 1;
DROP TABLE at1; DROP TABLE at2; DROP TABLE mem; DROP TABLE nmem;
